export function doctorHtml(profile){
 const pregnancy=profile?.caseStage==='pregnancy',born=['born','adopted','adoption-placed','foster','related-foster','professional','family-home'].includes(profile?.caseStage);
 return `<div class="case-page-heading"><span class="eyebrow">Wsparcie medyczne</span><h1>Kontakt z lekarzem</h1><p>Jeśli coś budzi Wasze wątpliwości, porozmawiajcie z lekarzem. Konsultacja pomaga wyjaśnić objawy, ustalić dalsze postępowanie i potrzebne badania lub zaświadczenia. Kalkulator nie zastępuje oceny medycznej.</p></div><div class="case-card-grid"><section class="case-card"><h2>${pregnancy?'Lekarz prowadzący ciążę':born?'Lekarz dziecka i lekarz rodzinny':'Lekarz rodzinny lub właściwy specjalista'}</h2><p>${pregnancy?'Pytania o przebieg ciąży, badania i niepokojące objawy omów z ginekologiem prowadzącym ciążę. Jeżeli nie masz jeszcze lekarza prowadzącego, umów konsultację ginekologiczną. W sprawach ogólnego stanu zdrowia możesz również zwrócić się do lekarza rodzinnego.':born?'W sprawach zdrowia dziecka skontaktujcie się z jego pediatrą lub lekarzem POZ. Wątpliwości dotyczące zdrowia rodzica warto omówić z lekarzem rodzinnym, a kontrolę po porodzie — z ginekologiem.':'Zacznijcie od lekarza rodzinnego, który pomoże ocenić problem i ustalić, czy potrzebna jest konsultacja specjalistyczna. Przy planowaniu ciąży można również umówić konsultację ginekologiczną.'}</p></section><section class="case-card"><h2>Umówienie wizyty przez ZnanyLekarz</h2><p>Na platformie ZnanyLekarz można wyszukać lekarza i dostępny termin wizyty w gabinecie lub konsultacji online. To dodatkowa możliwość znalezienia pomocy, gdy chcecie omówić pytania i dalsze postępowanie.</p><p>Przed rezerwacją sprawdźcie zakres wizyty, jej cenę i dostępność konsultacji dla dziecka. Nie każdy problem można ocenić online.</p><a class="primary" href="https://www.znanylekarz.pl/" target="_blank" rel="noopener noreferrer">Przejdź do ZnanyLekarz ↗</a></section></div>`;
}
